     1|/*
     2| * IVX Investor-First Home Feed — ivxholding.com
     3| *
     4| * Enforces the CANONICAL home layout from the single source of truth
     5| * (GET /api/ivx/video-platform/home-feed) — the exact same sequence the
     6| * Android and iOS apps render:
     7| *
     8| *   Featured Deal 1–3 → 1 Featured Project Video → Deal 4–6 → 1 video → repeat
     9| *
    10| * Behaviour:
    11| *   • Reorders the rendered deal cards in #properties-grid to the canonical order.
    12| *   • Inserts exactly ONE featured project video card after every 3 deals.
    13| *   • Every video card is attached to a real project (name, city, phase,
    14| *     investment, ROI, minimum, progress %, View Deal + Invest Now).
    15| *   • Performance: poster image loads first; the video source attaches only
    16| *     when the card scrolls into view; only the next upcoming video preloads.
    17| *   • Admin publish (deal/video meta) updates this page automatically on the
    18| *     next load — no separate configuration.
    19| */
    20|(function () {
    21|  'use strict';
    22|  if (window.__ivxHomeFeedLoaded) return;
    23|  window.__ivxHomeFeedLoaded = true;
    24|
    25|  var API_CANDIDATES = ['https://api.ivxholding.com', 'https://ivx-holdings-platform.onrender.com'];
    26|  var HLS_CDN = 'https://cdn.jsdelivr.net/npm/hls.js@1.5.20/dist/hls.min.js';
    27|
    28|  var homeFeed = null;      /* canonical blocks from the backend */
    29|  var applying = false;     /* guard against observer feedback loops */
    30|
    31|  /* ---------- helpers ---------- */
    32|  function esc(s) {
    33|    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    34|      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    35|    });
    36|  }
    37|  function money(n) {
    38|    n = Number(n) || 0;
    39|    if (n >= 1000000) return '$' + (n / 1000000).toFixed(n % 1000000 === 0 ? 0 : 1) + 'M';
    40|    if (n >= 1000) return '$' + (n / 1000).toFixed(n % 1000 === 0 ? 0 : 1) + 'K';
    41|    return '$' + Math.round(n);
    42|  }
    43|  function parseMetric(v) {
    44|    if (v == null || v === '') return null;
    45|    var n = Number(v);
    46|    return isNaN(n) || n <= 0 ? null : n;
    47|  }
    48|  function formatRoi(n) {
    49|    if (n == null) return '';
    50|    if (n >= 100) return Math.round(n) + '%';
    51|    return n.toFixed(n % 1 === 0 ? 0 : 2) + '%';
    52|  }
    53|
    54|  function fetchHomeFeed(i) {
    55|    i = i || 0;
    56|    if (i >= API_CANDIDATES.length) return Promise.reject(new Error('all API hosts failed'));
    57|    return fetch(API_CANDIDATES[i] + '/api/ivx/video-platform/home-feed?limit=60')
    58|      .then(function (r) {
    59|        var ct = (r.headers.get('content-type') || '').toLowerCase();
    60|        if (!r.ok || ct.indexOf('json') === -1) throw new Error('bad response');
    61|        return r.json();
    62|      })
    63|      .catch(function () { return fetchHomeFeed(i + 1); });
    64|  }
    65|
    66|  /* ---------- lazy HLS ---------- */
    67|  var hlsLoading = null;
    68|  function loadHlsJs() {
    69|    if (window.Hls) return Promise.resolve();
    70|    if (hlsLoading) return hlsLoading;
    71|    hlsLoading = new Promise(function (resolve) {
    72|      var s = document.createElement('script');
    73|      s.src = HLS_CDN; s.async = true;
    74|      s.onload = function () { resolve(); };
    75|      s.onerror = function () { resolve(); };
    76|      document.head.appendChild(s);
    77|    });
    78|    return hlsLoading;
    79|  }
    80|  function attachSource(video, hlsUrl, fallbackUrl) {
    81|    if (video.__ivxAttached) return;
    82|    video.__ivxAttached = true;
    83|    if (!hlsUrl) { if (fallbackUrl) video.src = fallbackUrl; return; }
    84|    if (video.canPlayType('application/vnd.apple.mpegurl')) { video.src = hlsUrl; return; }
    85|    loadHlsJs().then(function () {
    86|      if (window.Hls && window.Hls.isSupported()) {
    87|        var h = new window.Hls({ capLevelToPlayerSize: true, maxBufferLength: 15 });
    88|        h.on(window.Hls.Events.ERROR, function (_e, data) {
    89|          if (data && data.fatal) { try { h.destroy(); } catch (e) {} if (fallbackUrl) video.src = fallbackUrl; }
    90|        });
    91|        h.loadSource(hlsUrl);
    92|        h.attachMedia(video);
    93|        video.__ivxHls = h;
    94|      } else if (fallbackUrl) {
    95|        video.src = fallbackUrl;
    96|      }
    97|    });
    98|  }
