   100|  /* ---------- styles ---------- */
   101|  var css = ''
   102|    + '.ivx-hf-video{grid-column:1/-1;position:relative;background:#000;border-radius:16px;overflow:hidden;'
   103|    + 'min-height:360px;max-height:520px;display:flex;flex-direction:column}'
   104|    + '.ivx-hf-media{position:absolute;inset:0;background:#000;overflow:hidden}'
   105|    + '.ivx-hf-media img,.ivx-hf-media video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}'
   106|    + '.ivx-hf-gradient{position:absolute;left:0;right:0;bottom:0;height:320px;'
   107|    + 'background:linear-gradient(to top,rgba(0,0,0,.82),rgba(0,0,0,.55),transparent);z-index:2;pointer-events:none}'
   108|    + '.ivx-hf-tag{position:absolute;top:12px;left:12px;z-index:5;background:#FFD700;color:#000;border-radius:5px;'
   109|    + 'padding:3px 8px;font:800 10px/1 -apple-system,Segoe UI,sans-serif;text-transform:uppercase;letter-spacing:.4px}'
   110|    + '.ivx-hf-mute{position:absolute;top:12px;right:12px;z-index:5;background:rgba(0,0,0,.35);color:#fff;border:none;'
   111|    + 'border-radius:50%;width:38px;height:38px;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center}'
   112|    + '.ivx-hf-rail{position:absolute;right:10px;bottom:96px;z-index:5;display:flex;flex-direction:column;gap:16px;align-items:center}'
   113|    + '.ivx-hf-act{background:none;border:none;color:#fff;cursor:pointer;text-align:center;padding:0;'
   114|    + 'filter:drop-shadow(0 1px 3px rgba(0,0,0,.6))}'
   115|    + '.ivx-hf-act .ic{width:44px;height:44px;border-radius:50%;background:rgba(0,0,0,.25);display:flex;align-items:center;justify-content:center}'
   116|    + '.ivx-hf-act .i{font-size:24px;line-height:1;display:block}'
   117|    + '.ivx-hf-act .c{font:700 11px/1 -apple-system,sans-serif;margin-top:3px;display:block}'
   118|    + '.ivx-hf-act.on .ic{color:#e0245e}'
   119|    + '.ivx-hf-act.saved .ic{color:#E6C200}'
   120|    + '.ivx-hf-info{position:absolute;left:14px;right:84px;bottom:26px;z-index:5;color:#fff;pointer-events:none}'
   121|    + '.ivx-hf-badges{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}'
   122|    + '.ivx-hf-badge{display:inline-block;background:#FFD700;color:#000;border-radius:5px;padding:3px 8px;'
   123|    + 'font:800 10px/1 -apple-system,sans-serif;text-transform:uppercase;letter-spacing:.4px}'
   124|    + '.ivx-hf-badge.active{background:rgba(0,0,0,.55);border:1px solid #FFD700;color:#FFD700}'
   125|    + '.ivx-hf-name{font:800 22px/1.2 -apple-system,Segoe UI,sans-serif;text-shadow:0 1px 4px rgba(0,0,0,.7);margin-bottom:2px}'
   126|    + '.ivx-hf-loc{font:600 13px/1.3 -apple-system,sans-serif;color:rgba(255,255,255,.85);'
   127|    + 'text-shadow:0 1px 4px rgba(0,0,0,.7);margin-top:2px}'
   128|    + '.ivx-hf-subtitle{font:600 15px/1.3 -apple-system,sans-serif;color:rgba(255,255,255,.9);'
   129|    + 'text-shadow:0 1px 4px rgba(0,0,0,.7);margin-top:2px}'
   130|    + '.ivx-hf-stats{display:flex;gap:22px;margin-top:8px;flex-wrap:wrap}'
   131|    + '.ivx-hf-stat{text-align:center}'
   132|    + '.ivx-hf-stat .v{font:800 20px/1 -apple-system,sans-serif;color:#FFD700}'
   133|    + '.ivx-hf-stat .l{color:rgba(255,255,255,.75);font:600 10px/1 -apple-system,sans-serif;text-transform:uppercase;margin-top:4px}'
   134|    + '.ivx-hf-options{display:flex;gap:14px;margin-top:10px}'
   135|    + '.ivx-hf-opt{display:flex;flex-direction:column;align-items:center;gap:4px}'
   136|    + '.ivx-hf-opt .circ{width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;'
   137|    + 'background:rgba(0,0,0,.35);border:1.5px solid rgba(255,255,255,.25)}'
   138|    + '.ivx-hf-opt .circ.yellow{border-color:#FFD700;color:#FFD700}'
   139|    + '.ivx-hf-opt .circ.blue{border-color:#4A90D9;color:#4A90D9}'
   140|    + '.ivx-hf-opt .circ.green{border-color:#3CCF4E;color:#3CCF4E}'
   141|    + '.ivx-hf-opt .lab{font:600 10px/1 -apple-system,sans-serif;color:#fff}'
   142|    + '.ivx-hf-btns{display:flex;gap:10px;margin-top:14px;pointer-events:auto}'
   143|    + '.ivx-hf-btns a{flex:1;text-align:center;border-radius:999px;padding:13px 0;font:800 15px/1 -apple-system,Segoe UI,sans-serif;'
   144|    + 'text-decoration:none;cursor:pointer}'
   145|    + '.ivx-hf-view{background:rgba(0,0,0,.45);color:#FFD700;border:2px solid #FFD700}'
   146|    + '.ivx-hf-invest{background:#FFD700;color:#000}';
   147|  var styleEl = document.createElement('style');
   148|  styleEl.textContent = css;
   149|  document.head.appendChild(styleEl);
