   151|  /* SVG icons for the action rail and option circles */
   152|  var ICONS = {
   153|    heart: '&#9825;',
   154|    heartFilled: '&#10084;',
   155|    comment: '&#128172;',
   156|    bookmark: '&#128279;',
   157|    bookmarkFilled: '&#128278;',
   158|    share: '&#10148;',
   159|    mute: '&#128263;',
   160|    unmute: '&#128266;',
   161|    hex: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path></svg>',
   162|    users: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M22 21v-2a4 4 0 0 0-3-3.87"></path><path d="M16 3.13a4 4 0 0 1 0 7.75"></path></svg>',
   163|    home: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path><polyline points="9 22 9 12 15 12 15 22"></polyline></svg>'
   164|  };
   165|
   166|  /* ---------- featured project video card ---------- */
   167|  function buildVideoCard(v) {
   168|    var deal = v.deal || {};
   169|    var card = document.createElement('div');
   170|    card.className = 'ivx-hf-video';
   171|    card.setAttribute('data-ivx-home-feed-video', v.id);
   172|
   173|    var poster = v.poster_url || v.thumbnail_url || v.preview_blur_url || '';
   174|    var dealUrl = deal.url || 'https://ivxholding.com/?deal=' + encodeURIComponent(deal.id || v.id) + '#deals';
   175|    var title = deal.name || v.title || 'IVX Project';
   176|    var location = deal.city || '';
   177|    var roi = parseMetric(deal.expected_roi);
   178|    var minInvest = parseMetric(deal.min_investment);
   179|    var price = parseMetric(deal.price);
   180|    var minOwnership = (minInvest && price && price > 0) ? ((minInvest / price) * 100).toFixed(4) + '%' : null;
   181|    var dealType = (deal.deal_type || '').toLowerCase();
   182|    var isActive = (deal.status || v.status || 'published') === 'published';
   183|
   184|    var tokenized = { icon: ICONS.hex, label: 'Tokenized', cls: 'yellow' };
   185|    var jvDeals = { icon: ICONS.users, label: 'JV Deal', cls: 'blue' };
   186|    var buyers = { icon: ICONS.home, label: 'Buyer', cls: 'green' };
   187|    var options;
   188|    switch (dealType) {
   189|      case 'jv': case 'equity_split': case 'hybrid': options = [tokenized, jvDeals, buyers]; break;
   190|      case 'development': case 'new_construction': case 'rehab_construction': options = [jvDeals, tokenized, buyers]; break;
   191|      case 'profit_sharing': options = [tokenized, buyers, jvDeals]; break;
   192|      default: options = [tokenized, jvDeals, buyers];
   193|    }
   194|
   195|    var statsHtml = '';
   196|    if (price) statsHtml += '<div class="ivx-hf-stat"><div class="v">' + money(price) + '</div><div class="l">Investment</div></div>';
   197|    if (roi) statsHtml += '<div class="ivx-hf-stat"><div class="v">' + formatRoi(roi) + '</div><div class="l">ROI</div></div>';
   198|    if (minInvest) statsHtml += '<div class="ivx-hf-stat"><div class="v">' + money(minInvest) + '</div><div class="l">Minimum</div></div>';
   199|    if (!statsHtml && minOwnership) statsHtml += '<div class="ivx-hf-stat"><div class="v">' + esc(minOwnership) + '</div><div class="l">Min Ownership</div></div>';
   200|
   201|    var optionsHtml = options.map(function (opt) {
   202|      return '<div class="ivx-hf-opt"><div class="circ ' + opt.cls + '">' + opt.icon + '</div><div class="lab">' + esc(opt.label) + '</div></div>';
   203|    }).join('');
   204|
   205|    var hasDeal = !!(deal.id || v.id);
   206|    var ctaHtml = '';
   207|    if (hasDeal) {
   208|      ctaHtml = '<div class="ivx-hf-btns">'
   209|        + '<a class="ivx-hf-view" href="' + esc(dealUrl) + '">View Deal</a>'
   210|        + '<a class="ivx-hf-invest" href="' + esc(dealUrl) + '">Invest Now</a>'
   211|        + '</div>';
   212|    }
   213|
   214|    var badgesHtml = '';
   215|    if (hasDeal) badgesHtml += '<span class="ivx-hf-badge">Investment</span>';
   216|    if (isActive) badgesHtml += '<span class="ivx-hf-badge active">Active</span>';
   217|
   218|    card.innerHTML = ''
   219|      + '<div class="ivx-hf-media">'
   220|      + '  <span class="ivx-hf-tag">Featured Project Video</span>'
   221|      + (poster ? '<img src="' + esc(poster) + '" alt="' + esc(title) + '" loading="lazy"/>' : '')
   222|      + '  <video playsinline muted loop preload="none"' + (poster ? ' poster="' + esc(poster) + '"' : '') + ' style="opacity:0"></video>'
   223|      + '  <button class="ivx-hf-mute" aria-label="Unmute">' + ICONS.mute + '</button>'
   224|      + '  <div class="ivx-hf-gradient"></div>'
   225|      + '</div>'
   226|      + '<div class="ivx-hf-rail">'
   227|      + '  <button class="ivx-hf-act like' + (v.viewer_liked ? ' on' : '') + '"><span class="ic">' + (v.viewer_liked ? ICONS.heartFilled : ICONS.heart) + '</span><span class="c">' + fmt(v.like_count) + '</span></button>'
   228|      + '  <button class="ivx-hf-act cmt"><span class="ic">' + ICONS.comment + '</span><span class="c">' + fmt(v.comment_count) + '</span></button>'
   229|      + '  <button class="ivx-hf-act sav' + (v.viewer_saved ? ' saved' : '') + '"><span class="ic">' + (v.viewer_saved ? ICONS.bookmarkFilled : ICONS.bookmark) + '</span><span class="c">' + fmt(v.save_count) + '</span></button>'
   230|      + '  <button class="ivx-hf-act shr"><span class="ic">' + ICONS.share + '</span><span class="c">' + fmt(v.share_count) + '</span></button>'
   231|      + '</div>'
   232|      + '<div class="ivx-hf-info">'
   233|      + (badgesHtml ? '<div class="ivx-hf-badges">' + badgesHtml + '</div>' : '')
   234|      + '  <div class="ivx-hf-name">' + esc(title) + '</div>'
   235|      + (location ? '<div class="ivx-hf-loc">&#128205; ' + esc(location) + '</div>' : '')
   236|      + (statsHtml ? '<div class="ivx-hf-stats">' + statsHtml + '</div>' : '')
   237|      + (optionsHtml ? '<div class="ivx-hf-options">' + optionsHtml + '</div>' : '')
   238|      + ctaHtml
   239|      + '</div>';
   240|
   241|    var vid = card.querySelector('video');
   242|    var img = card.querySelector('.ivx-hf-media img');
   243|    var muteBtn = card.querySelector('.ivx-hf-mute');
   244|    var likeBtn = card.querySelector('.ivx-hf-act.like');
   245|    var saveBtn = card.querySelector('.ivx-hf-act.sav');
   246|    var shareBtn = card.querySelector('.ivx-hf-act.shr');
   247|
   248|    muteBtn.addEventListener('click', function () {
   249|      vid.muted = !vid.muted;
   250|      muteBtn.innerHTML = vid.muted ? ICONS.mute : ICONS.unmute;
   251|    });
   252|    likeBtn.addEventListener('click', function (e) {
   253|      e.stopPropagation();
   254|      toggleLike(v, likeBtn);
   255|    });
   256|    saveBtn.addEventListener('click', function (e) {
   257|      e.stopPropagation();
   258|      toggleSave(v, saveBtn);
   259|    });
   260|    shareBtn.addEventListener('click', function (e) {
   261|      e.stopPropagation();
   262|      shareVideo(v, shareBtn);
   263|    });
   264|
   265|    /* Lazy playback: attach the source ONLY when visible; images load first. */
   266|    card.__ivxActivate = function () {
   267|      attachSource(vid, v.hls_url, v.video_url);
   268|      vid.play().then(function () {
   269|        vid.style.opacity = '1';
   270|        if (img) img.style.opacity = '0';
   271|      }).catch(function () {});
   272|    };
   273|    card.__ivxDeactivate = function () { try { vid.pause(); } catch (e) {} };
   274|    card.__ivxPreload = function () {
   275|      /* preload the NEXT featured video only — metadata, no full download */
   276|      if (!vid.__ivxAttached) { vid.preload = 'metadata'; attachSource(vid, v.hls_url, v.video_url); }
   277|    };
   278|    return card;
   279|  }
