.live-deals-sub {
  font-size: 14px; color: var(--text2); margin-bottom: 32px; line-height: 1.65;
}
.live-deals-grid {
  display: flex; flex-direction: column; gap: 16px; align-items: center; max-width: 560px; margin: 0 auto;
}
@media(min-width: 560px) { .live-deals-grid { max-width: 560px; } }
.live-deal-card.ivx-app-card {
  width: 100%; max-width: 560px; background: #141414; border: 1px solid #2A2A2A;
  border-radius: 18px; overflow: hidden; transition: transform 0.22s, border-color 0.22s, box-shadow 0.22s;
}
.live-deal-card.ivx-app-card:hover {
  transform: translateY(-3px); border-color: #3A3A3A; box-shadow: 0 16px 40px rgba(0,0,0,0.35);
}
.ivx-card-gallery {
  position: relative; width: 100%; aspect-ratio: 16 / 10; overflow: hidden; background: #141414;
}
.ivx-card-gallery-slider {
  display: flex; width: 100%; height: 100%; overflow-x: auto; scroll-snap-type: x mandatory;
  scroll-behavior: smooth; -webkit-overflow-scrolling: touch; scrollbar-width: none;
}
.ivx-card-gallery-slider::-webkit-scrollbar { display: none; }
.ivx-card-gallery-slider img, .ivx-card-gallery-slider video {
  min-width: 100%; width: 100%; height: 100%; object-fit: cover; scroll-snap-align: start; flex: 0 0 100%;
}
.ivx-card-status-badge {
  position: absolute; top: 12px; left: 12px; z-index: 3;
  display: inline-flex; align-items: center; gap: 5px;
  background: rgba(0,0,0,0.55); border: 1px solid rgba(255,255,255,0.15);
  border-radius: 100px; padding: 4px 10px; font-size: 10px; font-weight: 900; letter-spacing: 0.5px;
  text-transform: uppercase; color: #fff;
}
.ivx-card-status-badge.pending { color: #F59E0B; border-color: rgba(245,158,11,0.35); }
.ivx-card-status-badge.active { color: #00C48C; border-color: rgba(0,196,140,0.35); }
.ivx-card-status-dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.ivx-card-photo-count {
