function initGallerySliders() {
  ensureDealPostMedia();
  document.querySelectorAll('.live-deal-gallery-slider').forEach(function(slider) {
    var dotsContainer = slider.parentElement.querySelector('.live-deal-photo-dots') || slider.parentElement.querySelector('.gallery-dots');
    if (!dotsContainer) return;
    var imgs = slider.querySelectorAll('img, video');
    if (imgs.length <= 1) return;
    if (slider._ivxScrollBound) return;
    slider._ivxScrollBound = true;
    var countEl = slider.parentElement.querySelector('.live-deal-photo-count');
    slider.addEventListener('scroll', function() {
      var scrollLeft = slider.scrollLeft;
      var w = slider.offsetWidth;
      var idx = Math.round(scrollLeft / w);
      var dots = dotsContainer.querySelectorAll('.live-deal-photo-dot, .cr-dot-item');
      dots.forEach(function(dot, i) {
        if (i === idx) dot.classList.add('active');
        else dot.classList.remove('active');
      });
      if (countEl) countEl.textContent = (idx + 1) + '/' + slider.querySelectorAll('img, video').length;
    }, { passive: true });
    dotsContainer.querySelectorAll('.live-deal-photo-dot, .cr-dot-item').forEach(function(dot) {
      dot.addEventListener('click', function() {
        var idx = parseInt(dot.getAttribute('data-idx'), 10);
        if (!isNaN(idx)) slider.scrollTo({ left: idx * slider.offsetWidth, behavior: 'smooth' });
      });
    });
  });

